-- Los IDENTITY siguen después del último id insertado a mano
ALTER TABLE municipio MODIFY id_municipio GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE tipo_prestador MODIFY id_tipo_prestador GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE rol MODIFY id_rol GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE tipo_componente MODIFY id_tipo_componente GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE prestador MODIFY id_prestador GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE usuario_sistema MODIFY id_usuario GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE destino MODIFY id_destino GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE paquete MODIFY id_paquete GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE plan MODIFY id_plan GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE componente MODIFY id_componente GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE salida MODIFY id_salida GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE cliente MODIFY id_cliente GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE perfil_cliente MODIFY id_perfil GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE pasajero MODIFY id_pasajero GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE cotizacion MODIFY id_cotizacion GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE reserva MODIFY id_reserva GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE pago MODIFY id_pago GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE notificacion MODIFY id_notificacion GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);

COMMIT;

-- Verificación: cantidad de filas por tabla
SELECT table_name, num_rows FROM (
  SELECT 'MUNICIPIO' AS table_name, COUNT(*) AS num_rows FROM municipio
  UNION ALL SELECT 'TIPO_PRESTADOR' AS table_name, COUNT(*) AS num_rows FROM tipo_prestador
  UNION ALL SELECT 'ROL' AS table_name, COUNT(*) AS num_rows FROM rol
  UNION ALL SELECT 'TIPO_COMPONENTE' AS table_name, COUNT(*) AS num_rows FROM tipo_componente
  UNION ALL SELECT 'PRESTADOR' AS table_name, COUNT(*) AS num_rows FROM prestador
  UNION ALL SELECT 'USUARIO_SISTEMA' AS table_name, COUNT(*) AS num_rows FROM usuario_sistema
  UNION ALL SELECT 'DESTINO' AS table_name, COUNT(*) AS num_rows FROM destino
  UNION ALL SELECT 'PAQUETE' AS table_name, COUNT(*) AS num_rows FROM paquete
  UNION ALL SELECT 'ITINERARIO_DIA' AS table_name, COUNT(*) AS num_rows FROM itinerario_dia
  UNION ALL SELECT 'PLAN' AS table_name, COUNT(*) AS num_rows FROM plan
  UNION ALL SELECT 'COMPONENTE' AS table_name, COUNT(*) AS num_rows FROM componente
  UNION ALL SELECT 'PAQUETE_COMPONENTE' AS table_name, COUNT(*) AS num_rows FROM paquete_componente
  UNION ALL SELECT 'SALIDA' AS table_name, COUNT(*) AS num_rows FROM salida
  UNION ALL SELECT 'CLIENTE' AS table_name, COUNT(*) AS num_rows FROM cliente
  UNION ALL SELECT 'PERFIL_CLIENTE' AS table_name, COUNT(*) AS num_rows FROM perfil_cliente
  UNION ALL SELECT 'PASAJERO' AS table_name, COUNT(*) AS num_rows FROM pasajero
  UNION ALL SELECT 'COTIZACION' AS table_name, COUNT(*) AS num_rows FROM cotizacion
  UNION ALL SELECT 'DETALLE_COTIZACION' AS table_name, COUNT(*) AS num_rows FROM detalle_cotizacion
  UNION ALL SELECT 'RESERVA' AS table_name, COUNT(*) AS num_rows FROM reserva
  UNION ALL SELECT 'RESERVA_PASAJERO' AS table_name, COUNT(*) AS num_rows FROM reserva_pasajero
  UNION ALL SELECT 'PAGO' AS table_name, COUNT(*) AS num_rows FROM pago
  UNION ALL SELECT 'PAGO_EN_LINEA' AS table_name, COUNT(*) AS num_rows FROM pago_en_linea
  UNION ALL SELECT 'NOTIFICACION' AS table_name, COUNT(*) AS num_rows FROM notificacion
) ORDER BY table_name;
